def factorial(n):
    if n < 0:
        return "Invalid input. Please enter a positive integer."
    elif n == 0:
        return 1
    else:
        result = 1
        for i in range(1, n+1):
            result *= i
        return result

print(factorial(5)) # Output: 120
print(factorial(-5)) # Output: Invalid input. Please enter a positive integer.

